308			cols[i] = table.Column{Title: c.Title, Width: c.MinWidth}
309		}
310		t := table.New(table.WithColumns(cols), table.WithFocused(true), table.WithHeight(10))
311	
312		bar := components.NewFilterBar()
313		if len(cfg.Tokens) > 0 {
314			bar = components.NewFilterBarWithTokens(cfg.Tokens)
315		}
316	
317		m := Model[T]{cfg: cfg, table: t, bar: bar, sortColumn: cfg.SortColumn, sortDesc: cfg.SortDesc, blinkOn: true, indicatorAt: -1}
318		for i, c := range cfg.Columns {
319			if c.Indicator != nil {
320				m.indicatorAt = i
321				break
322			}
323		}
324		// A frame from the start: a table whose view never calls AdvanceSpinner —
325		// one rendered in the same frame the action began — would otherwise show an
326		// empty status cell, which reads as "nothing is happening".
327		m.AdvanceSpinner()
328		// Through setStyles rather than the table alone: a table rendered before
329		// anything calls applyStyles — one built and drawn in the same frame — would
330		// otherwise render with the zero Styles, which carries no cell padding and
331		// so lays out two cells narrower per column than every width was solved for.
332		m.setStyles(theme.DefaultTableStyles())
333		// The invariant the rest of the file rests on: sortColumn is either -1 or a
334		// column that can actually be sorted by. Settling it once here is what lets
335		// CycleSort and sorted() stop re-checking — and what stops `.` getting stuck
336		// flipping the direction of a column with no comparator.
337		if m.sortColumn >= len(cfg.Columns) || (m.sortColumn >= 0 && cfg.Columns[m.sortColumn].Less == nil) {
338			m.sortColumn = -1
339			// A direction with no column to apply it to would put the header arrow

860	}
861	
862	// sorted orders the visible slice. SliceStable, because sort.Slice is not and
863	// two rows equal on the sort column would otherwise swap between rebuilds.
864	func (m *Model[T]) sorted(items []T) []T {
865		if m.sortColumn < 0 {
866			return items
867		}
868		less := m.cfg.Columns[m.sortColumn].Less // never nil — see New
869		desc := m.sortDesc
870		sort.SliceStable(items, func(i, j int) bool {
871			if desc {
872				return less(items[j], items[i])
873			}
874			return less(items[i], items[j])
875		})
876		return items
877	}
878	
879	// Span is one coloured run of a multi-run cell (Column.Spans): Width cells of
880	// the cell's already-fitted text, painted with Style. Style must not carry
881	// Width, Padding or Margin: they would change the cell's width (as for Cut).
882	type Span struct {
883		Width int
884		Style lipgloss.Style
885	}
886	
887	// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
888	// IconColumnWidth). It is the only way a view builds one. Only the first column
889	// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
890	func IndicatorColumn[T any](state func(T) indicator.State,
891		rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
892		c := Column[T]{
893			Sizing: SizingFixed, MinWidth: IconColumnWidth,
894			Indicator: state,
895			Cell: func(item T) string {
896				if rest == nil {
897					return ""
898				}
899				return rest(item)
900			},
901		}
902		if restStyle != nil {
903			c.Style = restStyle
904		}
905		return c
906	}
907	
908	// SetBlinkPhase sets the phase read at render. Read at render; nothing is rebuilt.
909	func (m *Model[T]) SetBlinkPhase(on bool) { m.blinkOn = on }
910	
911	// BlinkPhase reports the current blink phase.
912	func (m *Model[T]) BlinkPhase() bool { return m.blinkOn }
913

110		return line.String()
111	}
112	
113	// rowLine renders one row.
114	//
115	// A busy row shows the spinner in its status column instead of that column's
116	// own cell — on the selected row too. The glyph is the primary signal, and a
117	// signal that disappears under the cursor is one the user loses exactly when
118	// they are looking at it.
119	func (m *Model[T]) rowLine(cols []table.Column, item T, selected bool) string {
120		_, busy := m.busyLabel(item)
121	
122		var line strings.Builder
123		for i, c := range m.cfg.Columns {
124			if i >= len(cols) || cols[i].Width <= 0 {
125				continue
126			}
127			state := indicator.Idle
128			if c.Indicator != nil {
129				state = m.indicatorState(c, item, busy)
130			}
131			text := c.Cell(item)
132			switch {
133			case state != indicator.Idle:
134				text = indicator.Glyph(state, m.blinkOn)
135			case busy && m.indicatorAt < 0 && i == m.cfg.StatusColumn:
136				text = m.spinnerFrame
137			}
138			if state != indicator.Idle {
139				// Padded with runewidth, not lipgloss: lipgloss always counts an
140				// ambiguous-width glyph as one cell, runewidth follows the terminal.
141				fitted := runewidth.FillRight(text, cols[i].Width)
142				line.WriteString(m.indicatorCellStyle(state, selected).Render(fitted))
143				continue
144			}
145			fitted := fit(text, cols[i].Width, c.TruncateHead)
146			if !busy && (!selected || m.preserveColumnColors) {
147				if runs, ok := m.multiRunCell(c, item, fitted, selected); ok {
148					line.WriteString(runs)
149					continue
150				}
151			}
152			line.WriteString(m.cellStyle(c, item, selected, busy, i).Render(fitted))
153		}
154		if selected {
155			return m.styles.Selected.Render(m.padToContent(line.String()))
156		}
157		return line.String()
158	}
