package components

import (
	"slices"
	"strings"
	"unicode"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// RowQuery names one row: the registry snapshot, the current context, the
// row's target as the registry knows it, the kinds the view can rerun (nil =
// all), and what the view observes on its own (container, agent).
type RowQuery struct {
	Runs     []jobs.Run     // any context; filtered here
	Failures []jobs.Failure // any context; filtered here
	Context  string
	Target   string
	Kinds    []jobs.Kind
	// Observed is the view's own state (Idle if none); ObservedText is its
	// sentence without glyph, shown when Observed wins or on an idle row.
	Observed     indicator.State
	ObservedText string
}

// RowActivity is what the first column and the footer say about one row.
type RowActivity struct {
	State  indicator.State
	Detail RowDetail
}

// RowState resolves the row's state without building any text. It is what the
// activity column calls; DescribeRow agrees with it by construction.
func RowState(q RowQuery) indicator.State { return resolveRow(q).state }

// DescribeRow resolves the row and builds its footer sentence.
func DescribeRow(q RowQuery) RowActivity {
	f := resolveRow(q)
	a := RowActivity{State: f.state}
	glyph := indicator.Glyph(f.state, true) // the footer glyph never blinks
	switch {
	case len(f.active) > 0:
		it := f.active[0]
		a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(it.Item.Name())}
		if f.state == indicator.Running {
			a.Detail.Lead = it.Kind.Verb() + " "
		} else {
			a.Detail.Lead = "Queued: " + string(it.Kind) + " "
		}
		a.Detail.Tail = maskedSuffix(f.failures)
	case len(f.failures) > 0:
		fl := f.failures[0]
		a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(failureName(fl)),
			Tail: ": last " + string(fl.Kind) + " failed" + causeSuffix(fl.Kind, fl.Detail) + maskedSuffix(f.failures[1:])}
	default:
		// No job and no failure: the view's own sentence. Idle shows it with no
		// glyph (D8); any other observed state shows it with the glyph.
		a.Detail = RowDetail{Lead: oneLine(q.ObservedText)}
		if f.state != indicator.Idle && a.Detail.Lead != "" {
			a.Detail.Glyph = glyph
		}
	}
	return a
}

// FailureEvent is the 3-second Error a view posts when an operation fails:
// "Failed to <kind> <target> — <cause>".
func FailureEvent(kind jobs.Kind, target, cause string) string {
	return "Failed to " + string(kind) + " " + targetDisplay(target) + causeSuffix(kind, cause)
}

// rowFacts is the single computation behind RowState and DescribeRow.
type rowFacts struct {
	state    indicator.State
	active   []jobs.Active  // running first, then queued
	failures []jobs.Failure // newest first; the winner when state is Failed
}

func resolveRow(q RowQuery) rowFacts {
	f := rowFacts{
		active:   jobs.ActiveOn(q.Runs, q.Context, q.Target, q.Kinds...),
		failures: jobs.FailuresOn(q.Failures, q.Context, q.Target, q.Kinds...),
	}
	slices.SortStableFunc(f.failures, func(a, b jobs.Failure) int { return b.At.Compare(a.At) })
	act := indicator.Activity{Failed: len(f.failures) > 0, Observed: q.Observed}
	for _, a := range f.active {
		act.Running = act.Running || a.Item.State == jobs.ItemRunning
		act.Queued = act.Queued || a.Item.State == jobs.ItemQueued
	}
	f.state = indicator.Resolve(act)
	return f
}

// failureName is the target as the launcher wants it printed.
func failureName(f jobs.Failure) string {
	if f.Display != "" {
		return f.Display
	}
	return f.Target
}

// targetDisplay folds the home directory of an absolute path; an image
// reference or a forge path is kept verbatim.
func targetDisplay(s string) string {
	s = oneLine(s)
	if isPathTarget(s) {
		return theme.FoldHome(s)
	}
	return s
}

// causeSuffix is " — <cause>", or "" when there is no cause. The cause is put
// on one line and loses a leading "<kind> failed" (the sentence says it) with
// the separator that follows it.
func causeSuffix(kind jobs.Kind, detail string) string {
	cause := oneLine(detail)
	if p := string(kind) + " failed"; len(cause) >= len(p) && strings.EqualFold(cause[:len(p)], p) {
		cause = cause[len(p):]
		if cause == "" || cause[0] == ' ' || cause[0] == ':' || cause[0] == '-' || strings.HasPrefix(cause, "—") {
			cause = strings.TrimSpace(trimSeparator(strings.TrimSpace(cause)))
		} else {
			cause = p + cause
		}
	}
	if cause == "" {
		return ""
	}
	return " — " + cause
}

// trimSeparator removes one leading "—", "--", "-" or ":".
func trimSeparator(s string) string {
	for _, sep := range []string{"—", "--", "-", ":"} {
		if rest, ok := strings.CutPrefix(s, sep); ok {
			return rest
		}
	}
	return s
}

// maxTextRunes bounds free text before it is processed.
const maxTextRunes = 512

// oneLine is the single normalization of free text (causes, targets, observed
// sentences): it keeps the first maxTextRunes runes, drops invalid UTF-8 and Unicode format
// characters (bidi overrides, zero-width), turns control characters into
// spaces and collapses whitespace runs, so the text never spans more than one
// footer line.
func oneLine(s string) string {
	if n := 0; len(s) > maxTextRunes {
		for i := range s {
			if n == maxTextRunes {
				s = s[:i]
				break
			}
			n++
		}
	}
	s = strings.ToValidUTF8(s, "")
	s = strings.Map(func(r rune) rune {
		switch {
		case unicode.Is(unicode.Cf, r):
			return -1
		case unicode.IsControl(r):
			return ' '
		}
		return r
	}, s)
	return strings.Join(strings.Fields(s), " ")
}

// maskedSuffix lists the failure kinds a winner hides, in jobs.Kinds() order.
func maskedSuffix(masked []jobs.Failure) string {
	var names []string
	for _, k := range jobs.Kinds() {
		if slices.ContainsFunc(masked, func(f jobs.Failure) bool { return f.Kind == k }) {
			names = append(names, string(k))
		}
	}
	switch len(names) {
	case 0:
		return ""
	case 1:
		return " · earlier failure: " + names[0] + " (see :jobs)"
	}
	return " · earlier failures: " + strings.Join(names, ", ") + " (see :jobs)"
}

package components

import (
	"path/filepath"
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// JobsStatusLine is what a footer says while work runs (D9).
//
// It is derived every frame rather than posted as a message, and Rule 128 says
// why: a batch outlives the three seconds a footer message gets, so a line set
// on the first repository would vanish while the tenth was still going.
//
// Three forms, and the third is a deliberate surrender:
//
//	Scanning — 3/12                     one kind, started by origin
//	Scanning — 3/12 · Syncing — 1/4      two kinds, both started by origin
//	3 jobs running — :jobs for details   anything else
//
// The degraded form is what a footer can honestly say about work it does not
// own. One line cannot carry four batches launched from three views, and a line
// that showed only the part it recognised would be worse than one that admits
// there is more.
//
// origin is the view asking. A view with no work of its own to name — the
// dashboard, which launches none — passes an empty ViewType and always gets the
// third form, which is the whole of what it has to say.
//
// It lives here rather than in internal/jobs because the third form names a
// command (`:jobs`), and that is interface copy; and here rather than in one
// view because two of them now say it.
func JobsStatusLine(runs []jobs.Run, origin command.ViewType) string {
	live := jobs.Unfinished(runs)
	if len(live) == 0 {
		return ""
	}

	mine := make([]jobs.Run, 0, len(live))
	for _, run := range live {
		if origin != "" && run.Origin == origin {
			mine = append(mine, run)
		}
	}

	// Anything started elsewhere, or more than one batch of a kind, and the
	// detailed line stops being able to tell the truth.
	if len(mine) != len(live) || !oneRunPerKind(mine) {
		return Plural(len(live), "job", "jobs") + " running — :jobs for details"
	}

	parts := make([]string, 0, len(mine))
	for _, kind := range jobs.Kinds() {
		for _, run := range mine {
			if run.Kind == kind {
				parts = append(parts, run.Kind.Verb()+" — "+
					strconv.Itoa(run.Done())+"/"+strconv.Itoa(run.Total()))
			}
		}
	}
	return strings.Join(parts, " · ")
}

// oneRunPerKind reports whether no two runs share a kind. Two scans at once are
// two counters, and "Scanning — 3/12 · Scanning — 1/2" reads as a bug.
func oneRunPerKind(runs []jobs.Run) bool {
	seen := make(map[jobs.Kind]bool, len(runs))
	for _, run := range runs {
		if seen[run.Kind] {
			return false
		}
		seen[run.Kind] = true
	}
	return true
}

// Plural writes a count with the right noun. Exported because three packages
// spell the same sentence now.
func Plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.Itoa(n) + " " + many
}

// rowSeparator joins a row's detail to the batch progress on the footer line.
const rowSeparator = " · "

// Thresholds under which a part of the row line is dropped rather than cut to
// a stub nobody can read.
const (
	minPathCols   = 6 // a ShortPath below this is just an ellipsis
	minDetailCols = 8 // a detail below this says nothing; the progress stands alone
)

// RowDetail is what the footer says about the selected row: an activity glyph,
// a lead-in, the target (a path or an image reference) and a tail. Only the
// target is ever shortened as a path, which is why it is a field of its own.
type RowDetail struct{ Glyph, Lead, Target, Tail string }

// IsZero reports whether the detail says nothing.
func (d RowDetail) IsZero() bool { return d == RowDetail{} }

// head is everything before the target.
func (d RowDetail) head() string {
	if d.Glyph == "" {
		return d.Lead
	}
	return d.Glyph + " " + d.Lead
}

// String is the detail at full length, the home directory folded.
func (d RowDetail) String() string { return d.head() + theme.FoldHome(d.Target) + d.Tail }

// fit renders the detail in at most room columns. A path target shrinks first
// (never below minPathCols, even when the tail is long), then the end of the
// detail is cut. An image reference is not a path and is only ever cut.
func (d RowDetail) fit(room int) string {
	full := d.String()
	if theme.StringWidth(full) <= room {
		return full
	}
	pathRoom := room - theme.StringWidth(d.head()) - theme.StringWidth(d.Tail)
	// With no tail the cut lands on the path itself, so reducing it below its
	// room first would only trade a readable prefix for an ellipsis.
	if isPathTarget(d.Target) && (pathRoom >= minPathCols || d.Tail != "") {
		full = d.head() + theme.ShortPath(d.Target, max(pathRoom, minPathCols)) + d.Tail
	}
	return theme.TruncateWidth(full, room)
}

// isPathTarget tells a filesystem path from an image reference such as
// "registry/ns/app:1.2", which ShortPath would mangle.
func isPathTarget(target string) bool {
	return filepath.IsAbs(target) || strings.HasPrefix(target, "~")
}

// RowStatusLine composes the footer line for a selected row: its detail, then
// the batch progress, on one line of at most width columns. The progress is
// what gives way last; the detail is dropped whole when fewer than
// minDetailCols are left for it (or fewer than it needs, if it is shorter).
func RowStatusLine(detail RowDetail, progress string, width int) string {
	switch {
	case width <= 0:
		return ""
	case detail.IsZero():
		return theme.TruncateWidth(progress, width)
	case progress == "":
		return detail.fit(width)
	}
	room := width - theme.StringWidth(rowSeparator) - theme.StringWidth(progress)
	if room < min(minDetailCols, theme.StringWidth(detail.String())) {
		return theme.TruncateWidth(progress, width)
	}
	return detail.fit(room) + rowSeparator + progress
}

